// Jonker-Volgenant algorithm
// cost: n x n matrix (row-major)
// returns: x[j] = row assigned to column j

void lap(int n, double *cc, int *x, int *y) {
    int i, j, k, i0, j0, j1, j1new, numfree, last;
    double *u, *v, *d, *pred;
    int *free, *colist;
    double min, h, umin, usubmin, v2;

    u = malloc(n * sizeof(double));
    v = malloc(n * sizeof(double));
    d = malloc(n * sizeof(double));
    pred = malloc(n * sizeof(int));
    free = malloc(n * sizeof(int));
    colist = malloc(n * sizeof(int));

    // initialize
    for (i = 0; i < n; i++) {
        u[i] = 0; v[i] = 0; x[i] = -1; y[i] = -1;
    }

    // column reduction
    for (j = n-1; j >= 0; j--) {
        // find min in column j
        i0 = 0; min = cc[0*n + j];
        for (i = 1; i < n; i++) {
            h = cc[i*n + j];
            if (h < min) { min = h; i0 = i; }
        }
        v[j] = min;
        if (y[i0] == -1) {
            y[i0] = j;
            x[j] = i0;
        } else {
            x[j] = i0;
            y[i0] = -2; // mark as "assigned to multiple"
        }
    }

    // reduction transfer
    numfree = 0;
    for (i = 0; i < n; i++) {
        if (y[i] == -1) {
            free[numfree++] = i;
        } else if (y[i] == -2) {
            // row i assigned to multiple columns; find the two smallest
            j1 = 0; min = cc[i*n + 0];
            j0 = -1; usubmin = DBL_MAX;
            for (j = 1; j < n; j++) {
                h = cc[i*n + j] - v[j];
                if (h < min) {
                    usubmin = min; min = h; j0 = j1; j1 = j;
                } else if (h < usubmin) {
                    usubmin = h; j0 = j;
                }
            }
            // j1 is the best column for row i, j0 is second best
            u[i] = usubmin;
            if (j0 >= 0) {
                v[j0] = v[j0] - (usubmin - min); // adjust
            }
            // assign row i to column j1
            y[i] = j1;
            x[j1] = i;
            // the column j1 was previously assigned to some row; that row becomes free
            // (handled in augmenting phase)
        }
    }
    ...
}
```

