#include <stdlib.h>
#include <stdint.h>
#include <string.h>

// Forward auction with epsilon scaling. cost: n x n double row-major.
// Returns assignment (row i -> col j). Also outputs total bids via *bids_out.
int64_t* auction_forward(double* cost, int n, double eps_final, long* bids_out) {
    double* price = calloc(n, sizeof(double));
    int64_t* person_to_obj = malloc(n * sizeof(int64_t));
    int64_t* obj_to_person = malloc(n * sizeof(int64_t));
    int64_t* unassigned = malloc(n * sizeof(int64_t));
    int64_t* result = malloc(n * sizeof(int64_t));

    double maxc = 0.0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (cost[i*n+j] > maxc) maxc = cost[i*n+j];

    double eps = maxc / 4.0;
    for (int i = 0; i < n; i++) { person_to_obj[i] = -1; obj_to_person[i] = -1; }
    int cnt = 0;
    for (int i = 0; i < n; i++) unassigned[cnt++] = i;

    long bids = 0;
    while (eps >= eps_final) {
        while (cnt > 0) {
            cnt--;
            bids++;
            int64_t i = unassigned[cnt];
            int64_t best_j = 0;
            double best_v = cost[i*n+0] + price[0];
            double second_v = 1e300;
            for (int j = 1; j < n; j++) {
                double v = cost[i*n+j] + price[j];
                if (v < best_v) { second_v = best_v; best_v = v; best_j = j; }
                else if (v < second_v) second_v = v;
            }
            double bid = second_v - best_v + eps;
            price[best_j] += bid;
            int64_t prev = obj_to_person[best_j];
            person_to_obj[i] = best_j;
            obj_to_person[best_j] = i;
            if (prev != -1) { person_to_obj[prev] = -1; unassigned[cnt++] = prev; }
        }
        eps *= 0.25;
        if (eps < eps_final) break;
        // unassign unhappy rows
        for (int i = 0; i < n; i++) {
            int64_t j = person_to_obj[i];
            double cur = cost[i*n+j] + price[j];
            double min_v = 1e300;
            for (int jj = 0; jj < n; jj++) {
                double v = cost[i*n+jj] + price[jj];
                if (v < min_v) min_v = v;
            }
            if (min_v < cur - eps) {
                obj_to_person[j] = -1;
                person_to_obj[i] = -1;
                unassigned[cnt++] = i;
            }
        }
    }
    memcpy(result, person_to_obj, n * sizeof(int64_t));
    *bids_out = bids;
    free(price); free(person_to_obj); free(obj_to_person); free(unassigned);
    return result;
}
